function basicHotelKey(value){
  return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f\u064B-\u065F\u0670ـ]/g,'').toLowerCase().replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[^a-z0-9\u0600-\u06ff]+/g,' ').trim();
}
function catalogHotelId(value){
  let hash=2166136261;
  for(const char of String(value||'')){hash^=char.codePointAt(0);hash=Math.imul(hash,16777619)}
  return`mk_${(hash>>>0).toString(36)}`;
}
const existingHotelKeys=new Set(HOTELS.flatMap(h=>[h.name,h.englishName].map(basicHotelKey).filter(Boolean)));
MAKKAH_HOTEL_CATALOG.forEach(h=>{
  if(existingHotelKeys.has(basicHotelKey(h.name))||existingHotelKeys.has(basicHotelKey(h.englishName)))return;
  HOTELS.push({id:catalogHotelId(h.englishName),name:h.name,englishName:h.englishName,aliases:h.aliases,mealPlan:'',rates:[]});
  existingHotelKeys.add(basicHotelKey(h.name));
  existingHotelKeys.add(basicHotelKey(h.englishName));
});

